-- Spread the end of the reset over the 4 maps: at level 300 Crywolf gave 64M exp/min, Kanturu I 58M, Aida 47M and
-- Kanturu III 46M; with these multipliers all of them give about 64M.
update config."GameMapDefinition" set "ExpMultiplier" = 1.1 where "Number" = 37;
update config."GameMapDefinition" set "ExpMultiplier" = 1.35 where "Number" = 33;
update config."GameMapDefinition" set "ExpMultiplier" = 1.4 where "Number" = 38;

select m."Number", m."ExpMultiplier", sum(sa."Quantity") as monsters
from config."GameMapDefinition" m join config."MonsterSpawnArea" sa on sa."GameMapId" = m."Id"
where m."Number" in (10, 33, 34, 37, 38) and sa."SpawnTrigger" = 0 group by 1, 2 order by 1;
commit;
